Author:     welpy-cw <h.w.forms@arcor.de>
AuthorDate: Mon Aug 17 20:35:00 2026 +0100
Commit:     brendan@thunderbird.net <brendan@thunderbird.net>
CommitDate: Thu Aug 20 10:31:12 2026 +0000

    Bug 450059 - Don't call endFolderLoading on folders being deleted. r=mkmelin

    When the folder displayed by a DBViewWrapper is deleted, the wrapper is
    notified via FolderNotificationHelper and calls close(true). The
    folderIsDead flag already existed to avoid calling back into the dying
    folder (onLeavingFolder is skipped for dead folders), but the folder
    loading state was still torn down unconditionally, which called
    endFolderLoading() on the deleted folder.

    endFolderLoading() re-registers the folder as a DB change listener and
    runs UpdateSummaryTotals(true), which calls FlushToFolderCache(). For a
    folder that is being deleted this is harmful: RecursiveDelete has just
    removed the folder's entry from the folder cache and its summary file,
    and the stale folder object (still alive via strong references) would
    re-write its entry - including the Virtual flag, which is still set on
    the dying object. When a new folder is later created with the same name,
    it then incorrectly reads the Virtual flag back from the folder cache
    and becomes a saved search with the old scope and terms (bug 450059).

    Fix: honor the folderIsDead flag when clearing the folder loading state.
    close(folderIsDead) now passes it through to _setFolderLoading, which
    skips startFolderLoading()/endFolderLoading() for dead folders. Our own
    loading state and the listener are still updated, so the next view open
    starts from a clean state and the UI's loading state stays in sync.

    This only affects the dead-folder path; live folders keep the exact
    previous behavior (endFolderLoading still runs from _folderLoaded and
    from a normal mid-load close). Moving a folder to the trash is not
    affected: that goes through folderMoveCopyCompleted -> _folderMoved,
    which never calls close().

    As part of this change, the folderLoading getter/setter is converted
    into an isFolderLoading() method and a private _setFolderLoading()
    method so that the "folder being deleted" flag can be passed without a
    side-effectful setter.

    A regression test (mail/base/test/unit/test_viewWrapper_virtualFolderDeleted.js)
    opens a virtual folder in a DBViewWrapper, deletes it while it is
    displayed and checks that the folder cache entry is not re-added and
    that a folder created with the same name afterwards does not inherit the
    Virtual flag. Without this fix the test fails: the deleted folder's
    endFolderLoading re-adds its entry (with the Virtual flag) to the folder
    cache.

    To make sure a reused folder object behaves correctly after such an
    abandoned load, nsMsgDBFolder::SetParent now resets the database-listener
    state when a parentless folder is re-added to the tree. Without this, a
    non-virtual folder deleted while it was loading would not re-attach its
    database listener after being reused for a new folder with the same name.

    Differential Revision: https://phabricator.services.mozilla.com/D315858

diff --git a/mail/base/test/unit/test_viewWrapper_virtualFolderDeleted.js b/mail/base/test/unit/test_viewWrapper_virtualFolderDeleted.js
new file mode 100644
index 00000000000..5c166a28ecd
--- /dev/null
+++ b/mail/base/test/unit/test_viewWrapper_virtualFolderDeleted.js
@@ -0,0 +1,92 @@
+/* This Source Code Form is subject to the terms of the Mozilla Public
+ * License, v. 2.0. If a copy of the MPL was not distributed with this
+ * file, You can obtain one at http://mozilla.org/MPL/2.0/. */
+
+/**
+ * Test bug 450059: a virtual folder (saved search) that is deleted while it is
+ * displayed in a DBViewWrapper must not be resurrected.
+ *
+ * The view wrapper's close() used to call endFolderLoading() even for folders
+ * being deleted, which runs UpdateSummaryTotals() -> FlushToFolderCache() and
+ * re-writes the folder cache entry (including the Virtual flag) for a folder
+ * whose cache entry and summary file were just removed by the deletion. A
+ * subsequent folder created with the same name would then incorrectly read the
+ * Virtual flag back from the cache.
+ */
+
+/* import-globals-from resources/viewWrapperTestUtils.js */
+load("resources/viewWrapperTestUtils.js");
+initViewWrapperTestUtils({ mode: "local" });
+
+var { MailServices } = ChromeUtils.importESModule(
+  "resource:///modules/MailServices.sys.mjs"
+);
+
+/**
+ * Deleting a virtual folder that is displayed in a view wrapper must not
+ * re-add its entry to the folder cache (bug 450059).
+ */
+add_task(async function test_deleted_virtual_folder_not_reflushed_to_cache() {
+  const viewWrapper = make_view_wrapper();
+
+  const [[folderOne]] = await messageInjection.makeFoldersWithSets(1, [{}]);
+  const virtFolder = messageInjection.makeVirtualFolder([folderOne], {});
+  await view_open(viewWrapper, virtFolder);
+  Assert.ok(viewWrapper.isVirtual);
+
+  // For a non-server folder the folder cache key is the persistent descriptor
+  // of its summary file.
+  const cache = MailServices.accounts.folderCache;
+  const cacheKey = virtFolder.summaryFile.persistentDescriptor;
+
+  // The entry exists while the folder exists. getCacheElement throws
+  // NS_ERROR_NOT_AVAILABLE when the key is not present.
+  cache.getCacheElement(cacheKey, false);
+
+  const parent = virtFolder.parent;
+  parent.propagateDelete(virtFolder, true);
+  Assert.equal(virtFolder.parent, null, "deleted virtual folder has no parent");
+  Assert.equal(
+    viewWrapper.displayedFolder,
+    null,
+    "view wrapper should have closed on deletion"
+  );
+  Assert.ok(
+    !viewWrapper.isFolderLoading(),
+    "view wrapper should no longer be loading a folder"
+  );
+
+  // The deletion must not have re-added the folder's entry to the folder
+  // cache (the stale object would carry the Virtual flag).
+  Assert.throws(
+    () => cache.getCacheElement(cacheKey, false),
+    /NS_ERROR_NOT_AVAILABLE/,
+    "deleted folder should not be re-added to the folder cache"
+  );
+});
+
+/**
+ * Recreating a folder with the same name after deleting a displayed virtual
+ * folder must not inherit the Virtual flag (bug 450059).
+ */
+add_task(async function test_recreated_folder_does_not_inherit_virtual() {
+  const viewWrapper = make_view_wrapper();
+
+  const [[folderOne]] = await messageInjection.makeFoldersWithSets(1, [{}]);
+  const virtFolder = messageInjection.makeVirtualFolder([folderOne], {});
+  await view_open(viewWrapper, virtFolder);
+
+  const parent = virtFolder.parent;
+  const name = virtFolder.name;
+  parent.propagateDelete(virtFolder, true);
+
+  const recreated = parent.addSubfolder(name);
+  Assert.notEqual(recreated, virtFolder, "recreated folder should be fresh");
+  Assert.ok(
+    !recreated.getFlag(Ci.nsMsgFolderFlags.Virtual),
+    "recreated folder should not inherit the Virtual flag"
+  );
+
+  // Clean up the recreated folder.
+  recreated.parent.propagateDelete(recreated, true);
+});
